import fs from "fs/promises";
import { existsSync } from "fs";
import path from "path";
import { parse } from "@babel/parser";
import MagicString from "magic-string";
import resolveTailwindConfig from "tailwindcss/resolveConfig.js";
import * as esbuild from "esbuild";
import { walk } from "estree-walker";

const JSX_FILE_EXTENSIONS = new Set([".jsx", ".tsx"]);
const MAX_DIR_TRAVERSAL = 25; // A reasonable limit to prevent infinite loops

const getProjectRootDir = (initialPath = process.cwd()) => {
    let currentDir = initialPath;
    for (let i = 0; i < MAX_DIR_TRAVERSAL; i++) {
        if (existsSync(path.join(currentDir, "package.json"))) {
            return currentDir;
        }
        const parentDir = path.dirname(currentDir);
        if (parentDir === currentDir) break;
        currentDir = parentDir;
    }
    console.warn(
        `[greta-component-tagger] Could not find project root in ${MAX_DIR_TRAVERSAL} levels. Defaulting to ${process.cwd()}`
    );
    return process.cwd();
};

const threeFiberElements = new Set([
    "mesh",
    "group",
    "scene",
    "camera",
    "perspectiveCamera",
    "orthographicCamera",
    "ambientLight",
    "directionalLight",
    "spotLight",
    "pointLight",
    "rectAreaLight",
    "hemisphereLight",
    "primitive",
    "points",
    "lineSegments",
    "lineLoop",
    "sprite",
    "instancedMesh",
    "skinnedMesh",
    "bufferGeometry",
    "boxGeometry",
    "sphereGeometry",
    "cylinderGeometry",
    "planeGeometry",
    "torusGeometry",
    "torusKnotGeometry",
    "coneGeometry",
    "circleGeometry",
    "shapeGeometry",
    "latheGeometry",
    "extrudeGeometry",
    "tubeGeometry",
    "material",
    "meshBasicMaterial",
    "meshStandardMaterial",
    "meshPhysicalMaterial",
    "meshPhongMaterial",
    "meshToonMaterial",
    "meshLambertMaterial",
    "meshDepthMaterial",
    "meshDistanceMaterial",
    "meshNormalMaterial",
    "meshMatcapMaterial",
    "shaderMaterial",
    "pointsMaterial",
    "spriteMaterial",
    "lineBasicMaterial",
    "lineDashedMaterial",
    "shadowMaterial",
    "fog",
    "fogExp2",
    "texture",
    "canvasTexture",
    "cubeTexture",
    "dataTexture",
    "videoTexture",
    "compressedTexture",
    "depthTexture",
    "color",
    "vector2",
    "vector3",
    "vector4",
    "matrix3",
    "matrix4",
    "euler",
    "quaternion",
    "bufferAttribute",
    "instancedBufferAttribute",
    "raycaster",
    "axesHelper",
    "gridHelper",
    "polarGridHelper",
    "cameraHelper",
    "directionalLightHelper",
    "pointLightHelper",
    "spotLightHelper",
    "hemisphereLightHelper",
    "arrowHelper",
    "boxHelper",
    "box3Helper",
    "skeletonHelper",
    "ambientLightProbe",
    "hemisphereLightProbe",
    "audioListener",
    "positionalAudio",
    "lOD",
    "bone",
    "skeleton",
    "OrbitControls",
    "useGLTF",
    "Environment",
    "Sky",
    "Stars",
    "ContactShadows",
    "PresentationControls",
    "Html",
    "Text",
    "Float",
    "MeshReflectorMaterial",
    "MeshWobbleMaterial",
    "Shadow",
]);

const shouldAnnotateElement = (jsxName, dreiImports, dreiNamespaces) => {
    if (threeFiberElements.has(jsxName)) return false;
    if (dreiImports.has(jsxName)) return false;
    if (jsxName.includes(".")) {
        const [namespace] = jsxName.split(".");
        if (dreiNamespaces.has(namespace)) return false;
    }
    return true;
};

export const componentGretaTagger = () => {
    const rootDir = getProjectRootDir();
    const inputTailwindConfig = path.resolve(rootDir, "tailwind.config.ts");
    const outputTailwindConfig = path.resolve(
        rootDir,
        "./src/tailwind.config.greta.json"
    );
    const tmpTailwindConfig = path.resolve(rootDir, "./.tmp.tailwind.greta.js");
    const isDev = process.env.GRETA_DEV === "true";

    return {
        name: "greta-component-tagger",
        enforce: "pre",

        async transform(source, id) {
            if (
                !JSX_FILE_EXTENSIONS.has(path.extname(id)) ||
                id.includes("node_modules")
            )
                return null;

            let ast;
            try {
                ast = parse(source, {
                    sourceType: "module",
                    plugins: ["jsx", "typescript"],
                });
            } catch (e) {
                console.error(
                    `[greta-component-tagger] Failed to parse AST for file: ${id}`
                );
                console.error(e);
                return null;
            }

            const magicSource = new MagicString(source);
            const filePath = path.relative(rootDir, id);

            const dreiImports = new Set();
            const dreiNamespaces = new Set();

            // Collect imports in a single pass
            walk(ast, {
                enter(node, parent) {
                    if (
                        node.type === "ImportDeclaration" &&
                        node.source.value.includes("@react-three/drei")
                    ) {
                        node.specifiers.forEach((specifier) => {
                            if (specifier.type === "ImportSpecifier") {
                                dreiImports.add(specifier.local.name);
                            } else if (
                                specifier.type === "ImportNamespaceSpecifier"
                            ) {
                                dreiNamespaces.add(specifier.local.name);
                            }
                        });
                    }

                    // Check for and annotate JSX elements in the same pass
                    if (node.type === "JSXOpeningElement") {
                        const { name, attributes, loc } = node;

                        let jsxName;
                        if (name.type === "JSXIdentifier") {
                            jsxName = name.name;
                        } else if (name.type === "JSXMemberExpression") {
                            jsxName = `${name.object.name}.${name.property.name}`;
                        } else {
                            return;
                        }

                        if (
                            jsxName === "Fragment" ||
                            jsxName === "React.Fragment"
                        )
                            return;

                        if (
                            !shouldAnnotateElement(
                                jsxName,
                                dreiImports,
                                dreiNamespaces
                            )
                        )
                            return;

                        let isEditable = false;
                        if (
                            parent &&
                            parent.children &&
                            parent.children.length > 0
                        ) {
                            const hasDynamicContent = parent.children.some(
                                (child) =>
                                    child.type === "JSXExpressionContainer"
                            );
                            const hasSignificantText = parent.children.some(
                                (child) =>
                                    child.type === "JSXText" &&
                                    /\S/.test(child.value)
                            );
                            if (hasSignificantText && !hasDynamicContent) {
                                isEditable = true;
                            }
                        }

                        const line = loc.start.line;
                        const col = loc.start.column;
                        const componentId = `${filePath}:${line}:${col}`;

                        const attrs = attributes.reduce((acc, attr) => {
                            if (attr.type === "JSXAttribute" && attr.value) {
                                const val =
                                    attr.value.type === "StringLiteral"
                                        ? attr.value.value
                                        : attr.value.expression?.type ===
                                          "StringLiteral"
                                        ? attr.value.expression.value
                                        : ""; // Only capture string literals
                                if (val) acc[attr.name.name] = val;
                            }
                            return acc;
                        }, {});

                        const componentPath = filePath.replace(/\\/g, "/");
                        const componentFile = path.basename(filePath);
                        const componentContent = encodeURIComponent(
                            JSON.stringify(attrs)
                        );

                        const annotation = [
                            `data-greta-id="${componentId}"`,
                            `data-greta-name="${jsxName}"`,
                            `data-greta-editable="${isEditable}"`,
                            `data-component-path="${componentPath}"`,
                            `data-component-line="${line}"`,
                            `data-component-file="${componentFile}"`,
                            `data-component-name="${jsxName}"`,
                            `data-component-content="${componentContent}"`,
                        ].join(" ");

                        magicSource.appendLeft(name.end, " " + annotation);
                    }
                },
            });

            return {
                code: magicSource.toString(),
                map: magicSource.generateMap({ hires: true }),
            };
        },

        async buildStart() {
            if (isDev) {
                await buildTailwindConfig();
            }
        },

        configureServer(server) {
            if (!isDev) return;
            server.watcher.add(inputTailwindConfig);
            server.watcher.on("change", async (fileChanged) => {
                if (
                    path.normalize(fileChanged) ===
                    path.normalize(inputTailwindConfig)
                ) {
                    await buildTailwindConfig();
                }
            });
        },
    };

    async function buildTailwindConfig() {
        try {
            await esbuild.build({
                entryPoints: [inputTailwindConfig],
                outfile: tmpTailwindConfig,
                bundle: true,
                format: "esm",
                banner: {
                    js: 'import { createRequire } from "module"; const require = createRequire(import.meta.url);',
                },
            });

            const importedConfig = await import(
                `${tmpTailwindConfig}?t=${Date.now()}`
            );

            const resolvedConfig = resolveTailwindConfig(
                importedConfig.default
            );
            await fs.writeFile(
                outputTailwindConfig,
                JSON.stringify(resolvedConfig, null, 2)
            );
        } catch (err) {
            console.error(
                `[greta-component-tagger] Error building Tailwind config from ${inputTailwindConfig}:`,
                err
            );
        } finally {
            await fs.unlink(tmpTailwindConfig).catch(() => {});
        }
    }
};
